package com.landosol.toolbox.clanbattle.recognition

import android.graphics.BitmapFactory
import android.util.Base64
import java.security.MessageDigest

data class BattleScreenTemplates(
    val startBattle: PixelImage,
    val loading: PixelImage,
)

internal data class EmbeddedBattleTemplate(
    val sha256: String,
    val base64Chunks: List<String>,
) {
    val base64: String get() = base64Chunks.joinToString("")
}

object EmbeddedBattleTemplateLoader {
    fun load(): BattleScreenTemplates = BattleScreenTemplates(
        startBattle = loadImage("start_battle"),
        loading = loadImage("loading"),
    )

    private fun loadImage(name: String): PixelImage {
        val source = encodedTemplates.getValue(name)
        val bytes = Base64.decode(source.base64, Base64.DEFAULT)
        require(bytes.sha256() == source.sha256) { "会战界面模板校验失败：$name" }
        val bitmap = requireNotNull(BitmapFactory.decodeByteArray(bytes, 0, bytes.size)) {
            "会战界面模板无法解码：$name"
        }
        val pixels = IntArray(bitmap.width * bitmap.height)
        bitmap.getPixels(pixels, 0, bitmap.width, 0, 0, bitmap.width, bitmap.height)
        return PixelImage(bitmap.width, bitmap.height, pixels).also { bitmap.recycle() }
    }

    private fun ByteArray.sha256(): String = MessageDigest.getInstance("SHA-256")
        .digest(this)
        .joinToString("") { "%02x".format(it) }

    internal val encodedTemplates = mapOf(
        "start_battle" to EmbeddedBattleTemplate(
            sha256 = "dfac26f386601f86f5905a2d0041c21f3bf4341fcb55c630646f3010f640ad1d",
            base64Chunks = listOf(
                "",
                "",
                "",
                "",
                "",
                "",
                "",
                "",
                "",
                "",
                "",
                "",
                "",
                "",
            ),
        ),
        "loading" to EmbeddedBattleTemplate(
            sha256 = "7729f5ca3ed787e976f0dacbf9a88a1e37f4ac098b15cdc23fa7c39c16b76842",
            base64Chunks = listOf(
                "",
                "",
                "",
                "",
                "",
            ),
        ),
    )
}
